import React from 'react';

export default function Sidebar({ currentSubPage, setCurrentSubPage, onLogoutClick, role = 'admin' }) {
  
  // 1️⃣ Admin Menu Items
  const adminMenuItems = [
    { name: 'Overview', icon: '🏠' },
    { name: 'Manage Teachers', icon: '🧑‍🏫' },
    { name: 'Manage Students', icon: '🧑‍🎓' },
    { name: 'Manage Subjects', icon: '📚' }, 
    { name: 'Manage Timetable', icon: '🏫' },
    { name: 'Reports', icon: '📊' },
    { name: 'Feedback', icon: '💬' },
    { name: 'Settings', icon: '⚙️' },
  ];

  // 2️⃣ Teacher Menu Items
  const teacherMenuItems = [
    { name: 'Overview', icon: '🏠' },
    { name: 'Manage Activities', icon: '🧩' },
    { name: 'Upload Materials', icon: '📂' },
    { name: 'Exams & Quizzes', icon: '📝' },
    { name: 'Student Progress', icon: '📈' },
    { name: 'Feedback', icon: '💬' },
    { name: 'Settings', icon: '⚙️' },
  ];

  // 3️⃣ Student Menu Items
  const studentMenuItems = [
    { name: 'Overview', icon: '🏠' },
    { name: 'Study Materials', icon: '📚' },
    { name: 'Lesson Activities', icon: '🧩' },
    { name: 'Exams & Quizzes', icon: '📝' },
    { name: 'Class Timetable', icon: '🗓️' },
    { name: 'Feedback', icon: '💬' },
    { name: 'Settings', icon: '⚙️' },
  ];

  // 🔄 Role එක අනුව අදාළ Menu Items ටික Select කරගැනීම
  let menuItems = adminMenuItems;
  if (role === 'teacher') menuItems = teacherMenuItems;
  if (role === 'student') menuItems = studentMenuItems;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%', padding: '20px 0' }}>
      
      {/* 🟢 Dynamic Menu Items List */}
      <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: '8px', padding: '0 15px', overflowY: 'auto' }}>
        {menuItems.map((item) => (
          <button
            key={item.name}
            onClick={() => setCurrentSubPage(item.name)}
            style={{
              width: '100%',
              textAlign: 'left',
              padding: '14px 20px',
              backgroundColor: currentSubPage === item.name ? 'rgba(255,255,255,0.15)' : 'transparent',
              color: 'white',
              border: 'none',
              borderRadius: '10px',
              cursor: 'pointer',
              fontSize: '15px',
              display: 'flex',
              alignItems: 'center',
              gap: '12px',
              fontWeight: currentSubPage === item.name ? 'bold' : 'normal',
              transition: '0.2s'
            }}
          >
            <span style={{ fontSize: '18px' }}>{item.icon}</span> {item.name}
          </button>
        ))}
      </div>

      {/* 🟢 Logout Button */}
      <div style={{ padding: '0 15px 30px 15px', marginTop: 'auto' }}>
        <button 
          onClick={onLogoutClick} 
          style={{
            width: '100%',
            padding: '12px',
            backgroundColor: '#ef4444',
            color: 'white',
            border: 'none',
            borderRadius: '8px',
            fontWeight: 'bold',
            cursor: 'pointer',
            transition: '0.3s',
            boxShadow: '0 4px 6px rgba(239, 68, 68, 0.2)'
          }}
        >
          Logout
        </button>
      </div>
    </div>
  );
}
